import os
from typing import Dict, Any
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def validate_required_fields(document_path: str, required_fields: Dict[str, float]) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id="prebuilt-invoice", document=f)
    result: AnalyzeResult = poller.result()
    extracted_fields = {}
    def extract_fields(fields_dict: Dict[str, Any], prefix: str = ""):
        for name, field in fields_dict.items():
            full_name = f"{prefix}.{name}" if prefix else name
            if field.content is not None and field.confidence is not None:
                extracted_fields[full_name] = {
                    "value": field.content,
                    "confidence": field.confidence
                }
            if hasattr(field, "fields") and field.fields:
                extract_fields(field.fields, full_name)
    extract_fields(result.fields)
    validation_results = {}
    is_valid = True
    for req_field, min_conf in required_fields.items():
        if req_field in extracted_fields:
            conf = extracted_fields[req_field]["confidence"]
            if conf >= min_conf:
                validation_results[req_field] = {"status": "valid", "confidence": conf}
            else:
                validation_results[req_field] = {"status": "low_confidence", "confidence": conf}
                is_valid = False
        else:
            validation_results[req_field] = {"status": "missing"}
            is_valid = False
    return {
        "overall_valid": is_valid,
        "extracted_fields": extracted_fields,
        "validation": validation_results
    }
